   226→func (a *OpenCodeAgent) WriteSession(session *agent.AgentSession) error {
   227→	if session == nil {
   228→		return errors.New("nil session")
   229→	}
   230→	if session.SessionRef == "" {
   231→		return errors.New("no session ref to write to")
   232→	}
