// countLines counts the number of non-empty lines in JSONL content.
func countLines(content string) int {
	if content == "" {
		return 0
	}
	lines := strings.Split(content, "\n")
	count := 0
	for _, line := range lines {
		if strings.TrimSpace(line) != "" {
			count++
		}
	}
	return count
}

